// Writes conformance/render.v1.json: the read side of the editor, generated by running the TypeScript reference.
//   inline        runs(markdown), inlineToPlain(markdown) and runsToMarkdown of the parsed runs
//   runsToMarkdown arbitrary run lists (underline, highlight, code with backticks, hrefs with parentheses...)
//   fromMarkdown  block-level markdown to blocks, with the options that change the result
//   documents     toMarkdown, toHTML, toPlainText, stats, getOutline and findBlocks of whole documents
//   words         countWords of single strings (Latin tokens and CJK characters)
// Go and Python must reproduce every case. Fuzz cases are seeded token soups; the reference decides every outcome.
import { writeFileSync } from 'node:fs';
import { b, chart, createDocument, createEditor, findBlocks, fromMarkdown, getOutline, op, runs, stats, toHTML, toMarkdown, toPlainText } from '../packages/core/src/index.js';
