import { countWords } from '../packages/core/src/stats.js';
import { inlineToPlain, runsToMarkdown } from '../packages/core/src/inline.js';

let seed = 20261110;
const rand = (n: number): number => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return (seed >>> 8) % n; };
const pick = <T,>(items: readonly T[]): T => items[rand(items.length)]!;
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

