const markdownSamples: { markdown: string; options: { idPrefix: string; parentId?: string | null; citationMarkers?: boolean } }[] = [];
const seenMd = new Set<string>();
const addMd = (markdown: string, options: { idPrefix: string; parentId?: string | null; citationMarkers?: boolean } = { idPrefix: 'md' }): void => {
  const key = JSON.stringify([markdown, options]); if (seenMd.has(key)) return; seenMd.add(key); markdownSamples.push({ markdown, options });
};
addMd(''); addMd('\n\n  \n'); addMd('# Title\n\nParagraph one\ncontinues here.\n\n- a\n- b\n  - c\n\n1. x\n2. y\n\n| h1 | h2 |\n| --- | ---: |\n| 1 | 2 |\n\n```ts\nconst x = 1;\n```\n\n> [!TIP]\n> **Tip title**\n> body\n\n> quote\n>\n> — Author\n\n---\n\n***\n\n[TOC]\n\n![img](https://example.com/p.png)\n');
addMd('Windows\r\nline endings\r\n\r\n- item\r\n', { idPrefix: 'win' });
addMd('text [^c1] marker', { idPrefix: 'cm', citationMarkers: false }); addMd('text [^c1] marker', { idPrefix: 'cm', citationMarkers: true });
