const BASE = '2026-11-10T09:00:00Z';
function build(name: string, steps: Operation[][]): ResearchDocument {
  let at = BASE;
  const editor = createEditor(createDocument({ id: `doc-${name}`, title: `Title for ${name} with *stars* & <tags>` }, { now: () => at }), { now: () => at });
  steps.forEach((operations, index) => {
    at = `2026-11-10T09:00:${String(index + 1).padStart(2, '0')}Z`;
    const result = editor.apply({ id: `tx-${name}-${index}`, actor: { id: 'conformance', kind: 'agent' }, baseRevision: editor.getSnapshot().revision, operations });
    if (!result.ok) throw new Error(`${name}: ${JSON.stringify(result.issues)}`);
  });
  return clone(editor.getSnapshot());
}
