const WORD_SAMPLES = ['', 'hello world', "don't stop", 'a-b-c', '3.14 and 1,000', '日本語です', 'ひらがなカタカナ', '漢字', 'mixed中文and English', 'x̂ combining', 'Ünïcödé', '٣٤٥', '’quoted’', "rock 'n' roll", 'a.b.c.', 'a..b', '-lead trail-', 'ǅ titlecase', '𝒜𝒷𝒸', '😀 emoji', 'ａｂｃ fullwidth', 'ｱｲｳ halfwidth kana', '々 iteration 〆', 'ー prolonged', '한국어', '１２３', 'tab\tsep\nnew', 'a b c', 'é é', 'x_y snake', "it's—dash", '𠀀 extension B', '㐀 ext A', '⺀ radical'];
const words = WORD_SAMPLES.map(text => ({ text, ...countWords(text) }));

const count = (value: unknown[]): number => value.length;
const note = 'Generated by scripts/export-render-conformance.ts from the TypeScript reference. See the script header for the sections. documents[] hold the input document and every rendering: markdown/html/text with default options and the "Bare" variants with title:false and a small chartRows (markdownBare/htmlBare use chartRows 2, textBare chartRows 1), htmlStandalone with standalone:true, stats, outline and findBlocks queries.';
const sections: Record<string, unknown[]> = { inline, runsToMarkdown: runsToMd, fromMarkdown: fromMd, badPrefixes, documents: documentCases, words };
const lines = Object.entries(sections).map(([key, list]) => `${JSON.stringify(key)}:[\n${list.map(item => JSON.stringify(item)).join(',\n')}\n]`);
writeFileSync(new URL('../conformance/render.v1.json', import.meta.url), `{"version":1,"note":${JSON.stringify(note)},\n${lines.join(',\n')}\n}\n`);
console.log(Object.fromEntries(Object.entries(sections).map(([key, list]) => [key, count(list)])));
